 public static void Sources(string label){Directory.CreateDirectory(Doc+"/sources");using var f=new FileStream(Doc+"/sources/"+label+".zip",FileMode.CreateNew);using var zip=new ZipArchive(f,ZipArchiveMode.Create);var hashes=new Dictionary<string,string>();foreach(var p in Directory.GetFiles("tools/viable-safe-contingency").Where(p=>!Directory.Exists(p)).Order()){var n=Path.GetFileName(p);hashes[n]=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p)));zip.CreateEntryFromFile(p,n,CompressionLevel.Optimal);}Save("sources/"+label+".json",hashes);}
