 public static void Main(string[] args){if(args.Length<1)throw new ArgumentException("Study154 OFF; explicit bounded flag required");var mode=args.Length>1?int.Parse(args[1]):1;var label=args.Length>2?args[2]:"v1";if(mode is <0 or >2)throw new ArgumentException("Only isolated S0/S1/S2 controllers; S3 is diagnostic");
