 public static Review151 Restore(string path,RiderSpec spec,Action guard){var root=Read<JsonElement>(path);var rt=new Runtime154(spec,false,Performance(1));var tapes=new Dictionary<string,Tape150>();foreach(var item in root.GetProperty("Tapes").EnumerateObject()){
  guard();var t=item.Value;var start=t.GetProperty("Start").Deserialize<State146>(Json)!;rt.Begin(start.Input.Time);var actions=t.GetProperty("Actions").Deserialize<FreeRacingAction[]>(Json)!;var state=start;var states=new List<State146>{start};var points=new List<FreeRacingPoint>();foreach(var action in actions){guard();var step=rt.Step(state,action);state=step.End;states.Add(state);points.AddRange(step.Prediction.Points.Skip(points.Count==0?0:1));}var safety=Clearance153.Check(points.ToArray(),Regime153.SafetyHalfMeter);if(!safety.Legal)throw new InvalidOperationException("Restored S policy failed");tapes.Add(item.Name,new(t.GetProperty("CreatedAt").GetDouble(),t.GetProperty("Goal").GetDouble(),t.GetProperty("SafetyGoal").GetDouble(),actions,states.ToArray(),points.ToArray(),t.GetProperty("Arrival").GetDouble(),safety,"restored own prior policy"));}
