 public static void Native(int mode,string version,double maximumSeconds,int laps,double cpuCap){if(!double.IsFinite(cpuCap)||cpuCap<=0||cpuCap>330)throw new ArgumentOutOfRangeException(nameof(cpuCap));var label="S"+mode+"-"+version;using var budget=new Budget154(label,1,cpuCap);Sources(label);Directory.CreateDirectory(Doc+"/native");using var journal=new Journal147(Doc+"/native/"+label+"-decisions.jsonl");var process=Process.GetCurrentProcess();Planner154? planner=null;var timings=new List<object>();double controller=0;int count=0;
  Decision144 Choose(FreeRacingInput i,CrankClutch144 crank,RiderSpec spec,TrackFrame frame,CoreSim.TrackStateSnapshot surface,WorldParameters p,float mass,float inertia,string variant){var began=process.TotalProcessorTime;bool returned=false;try{budget.Guard();planner??=new(spec,false,new(Enabled:true),budget.Guard,performance:Performance(mode));var d=planner.Choose(i,crank);var review=planner.Last!;var id="decision-"+count.ToString("D4");Save("policies/"+label+"/"+id+".json.gz",Evidence152.Compact(review));Save("diagnostics/"+label+"/"+id+".json.gz",new{RejectedRollouts=planner.RolloutDiagnostics,LocalCandidates=planner.Runtime.CandidateLog()});journal.Append(new{Event="decision",i.Time,Tree=id,Selected=d.Choice.Action,PhysicalHash=Bits152.Review(review),review.Independent,review.ConditionalCertificate,review.CpuSeconds,review.Counts,review.Profile,Nodes=review.Tree.Length,Leaves=review.Terminals.Length});count++;returned=true;if(count%25==0)Console.WriteLine(label+" t="+i.Time+" CPU="+budget.Elapsed);return d;}catch(InvalidOperationException e){Save("policies/"+label+"/abstain.json.gz",new{e.Message,Observed=i,CrankOmega=crank.Omega,Review=planner?.Last is {} r?Evidence152.Compact(r):null,Counts=planner?.Runtime.Counters()});Save("diagnostics/"+label+"/abstain.json.gz",new{RejectedRollouts=planner?.RolloutDiagnostics,LocalCandidates=planner?.Runtime.CandidateLog()});journal.Append(new{Event="abstain",i.Time,e.Message});throw;}finally{var cpu=(process.TotalProcessorTime-began).TotalSeconds;controller+=cpu;timings.Add(new{Time=i.Time,CpuSeconds=cpu,Returned=returned});}}
  Run144 run;using(var world=new NativeWorld153(new(Enabled:true,RequiredLaps:laps,MaximumSeconds:maximumSeconds),safetyHalfMeter:true))run=world.Run(label,"K1",Choose);Save("native/"+label+".json.gz",run);Save("timings/"+label+".json",timings);var samples=run.Riders[0].Samples;var passed=run.Outcome=="completed"&&run.Riders[0].CompletedLaps==laps&&run.Contacts.Length==0&&samples.Where(s=>s.Certificate is not null).All(s=>s.Certificate>=.5)&&samples.All(s=>Math.Min(s.Inner,s.Outer)>=.5);
  Save("native/"+label+"-result.json",new{Passed=passed,Mode=mode,MaximumNativeSeconds=maximumSeconds,RequiredLaps=laps,run.Outcome,run.EndSeconds,run.Fingerprint,run.Riders[0].FinishSeconds,run.Riders[0].CompletedLaps,Decisions=count,ControllerCpu=controller,CpuSeconds=budget.Elapsed,MinimumGap=samples.Min(s=>Math.Min(s.Inner,s.Outer)),MinimumSweep=samples.Where(s=>s.Certificate is not null).Min(s=>s.Certificate),Contacts=run.Contacts.Length,Violations=samples.Count(s=>Math.Min(s.Inner,s.Outer)<.5),Counts=planner?.Runtime.Counters()});budget.Finish(run.Outcome);Console.WriteLine(label+" PASS="+passed+" "+run.Outcome+" t="+run.EndSeconds+" CPU="+budget.Elapsed);
 }
